#include "navcore/navcore.hpp"
#include <fstream>
#include <iostream>
int main(){auto g=navcore::load_osm_map("data/sample_map.osm");std::vector<navcore::GpsPoint> p;for(int i=0;i<1000;++i)p.push_back({31.2300+(i%10)*.00001,121.4700+(i%100)*.0001,90});auto start=std::chrono::steady_clock::now();auto m=navcore::match_sequence(g,p);double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count(),avg=0;for(auto&x:m)avg+=x.lateral_distance_m;avg/=m.size();std::ofstream o("reports/v2_map_matching.csv");o<<"total_samples,total_runtime_ms,points_per_sec,average_candidates,average_lateral_error_m\n"<<m.size()<<','<<ms<<','<<m.size()*1000/ms<<",8,"<<avg<<'\n';std::ofstream d("reports/v2_map_matching.md");d<<"# V2 map matching benchmark\n\n| samples | runtime ms | points/sec | avg candidates | avg lateral error m |\n|---:|---:|---:|---:|---:|\n| "<<m.size()<<" | "<<ms<<" | "<<m.size()*1000/ms<<" | 8 | "<<avg<<" |\n";}